CREATE INDEX "accounts_customuser_user_permissions_customuser_id_0deaefae" ON "accounts_customuser_user_permissions" ("customuser_id");
CREATE INDEX "accounts_customuser_user_permissions_permission_id_aea3d0e5" ON "accounts_customuser_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE INDEX "services_appointment_client_id_2fed74fd" ON "services_appointment" ("client_id");
CREATE INDEX "services_notification_appointment_id_2f8a486a" ON "services_notification" ("appointment_id");
CREATE INDEX "services_notification_user_id_02fc477f" ON "services_notification" ("user_id");
